const inputJson = $input.first().json;
let responseStr = "";

if (inputJson.content && inputJson.content.parts && inputJson.content.parts.length > 0) {
  responseStr = inputJson.content.parts[0].text;
} else if (inputJson.text) {
  responseStr = inputJson.text;
} else if (inputJson.output) {
  responseStr = inputJson.output;
} else if (inputJson.message && inputJson.message.content) {
  responseStr = inputJson.message.content;
} else if (typeof inputJson === 'string') {
  responseStr = inputJson;
} else {
  responseStr = JSON.stringify(inputJson);
}

let cleanJson = typeof responseStr === 'string' ? responseStr.replace(/```json/gi, "").replace(/```/g, "").trim() : JSON.stringify(responseStr);

try {
  let data = JSON.parse(cleanJson);

  // Convert new array format to old format for OpenAI evaluator
  if (data.respuestas && Array.isArray(data.respuestas)) {
    let respuestas_estudiante = {};
    for (const item of data.respuestas) {
      respuestas_estudiante[item.numero] = item.opcion_marcada;
    }
    data = { nombre_estudiante: data.nombre_estudiante, respuestas_estudiante: respuestas_estudiante, raw_vision: data.respuestas };
  } else {
    if (data.evaluacion) data = data.evaluacion;
    if (data.resultado) data = data.resultado;
    if (data.response) data = data.response;
  }

  return {
    json: data
  };
} catch(e) {
  return {
    json: {
      error: "Error leyendo JSON de IA. " + e.message,
      raw: responseStr.substring(0, 100)
    }
  };
}

