const inputJson = $input.first().json;
let responseStr = "";

// OpenAI node returns output in 'message.content' or 'text' or 'choices[0].message.content'
if (inputJson.choices && inputJson.choices[0] && inputJson.choices[0].message) {
  responseStr = inputJson.choices[0].message.content;
} else if (inputJson.message && inputJson.message.content) {
  responseStr = inputJson.message.content;
} else if (inputJson.text) {
  responseStr = inputJson.text;
} else if (typeof inputJson === 'string') {
  responseStr = inputJson;
} else {
  responseStr = JSON.stringify(inputJson);
}

let cleanJson = typeof responseStr === 'string' ? responseStr.replace(/```json/gi, "").replace(/```/g, "").trim() : JSON.stringify(responseStr);

try {
  let data = JSON.parse(cleanJson);
  if (data.evaluacion) data = data.evaluacion;
  if (data.resultado) data = data.resultado;
  if (data.response) data = data.response;

  const webhookData = $node["Webhook"].json.body;
  const rawNota = data.nota !== undefined ? data.nota : (data.score !== undefined ? data.score : null);
  const nota = rawNota !== null && !isNaN(parseFloat(rawNota)) ? parseFloat(rawNota) : null;
  const retro = data.retroalimentacion || data.feedback || data.comentario || null;

  let estudiante_id = data.estudiante_id || null;
  let estudiante_nombre = undefined;

  if (estudiante_id && webhookData.estudiantes_lote) {
      const matched = webhookData.estudiantes_lote.find(e => e.id === estudiante_id);
      if (matched) {
          estudiante_nombre = matched.nombre;
      }
  }

  let result = {
      id: webhookData.evaluacion_id,
      nota: nota,
      retroalimentacion: retro,
      estudiante_id: estudiante_id,
      procesado_correctamente: nota !== null,
      error_ocr: nota === null ? "OpenAI no devolvió la nota. Recibido: " + JSON.stringify(data).substring(0, 150) : null
  };
  if (estudiante_nombre) {
      result.estudiante_nombre = estudiante_nombre;
  }

  return { json: result };
} catch(e) {
  const webhookData = $node["Webhook"].json.body;
  return {
    json: {
      id: webhookData.evaluacion_id,
      procesado_correctamente: false,
      error_ocr: "Error leyendo JSON final. " + e.message + " | Raw: " + responseStr.substring(0, 100)
    }
  };
}

